        t = dtypes.get(col) or (infer_type(values) if infer_types else "str")
        if t == "str":
            continue
        for lineno, r in enumerate(rows):
            if r[i] is not None:
                try:
                    r[i] = parse_value(r[i], t)
                except ValueError:
                    raise ValueError(f"column {col!r}: cannot parse {r[i]!r} as {t}") from None

